from model.strategy_type import StrategyType
from model.base import BaseStrategy
from functools import lru_cache

class MaxTargetCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:  
        data = message.message[0].data
        random_bag = data['random_bag']
        guess_bag = data['guess_bag']
        max_guess = data['max_guess']
        past_picks = len(guess_bag)
        remaining_picks = max_guess - past_picks
        bag_state_tuple = tuple(tuple(sorted(bag)) for bag in random_bag)

        @lru_cache(None)
        def exp_sum_if_pick(rem_picks: int, bag_state: tuple, i: int) -> float:
            if len(bag_state[i]) == 0:
                return float('-inf')
            coins = list(bag_state[i])
            len_coins = len(coins)
            sum_exp = 0.0
            for idx in range(len_coins):
                c = coins[idx]
                new_coins_list_i = [coins[j] for j in range(len_coins) if j != idx]
                new_coins_i_tuple = tuple(sorted(new_coins_list_i))
                new_bag_state_list = list(bag_state)
                new_bag_state_list[i] = new_coins_i_tuple
                new_bag_state_tuple_new = tuple(new_bag_state_list)
                sum_exp += c + max_expected_sum(rem_picks - 1, new_bag_state_tuple_new)
            return sum_exp / len_coins

        @lru_cache(None)
        def max_expected_sum(rem_picks: int, bag_state: tuple) -> float:
            if rem_picks == 0 or all(len(b) == 0 for b in bag_state):
                return 0.0
            max_sum_val = float('-inf')
            for i in range(len(bag_state)):
                if len(bag_state[i]) > 0:
                    exp_sum_i = exp_sum_if_pick(rem_picks, bag_state, i)
                    if exp_sum_i > max_sum_val:
                        max_sum_val = exp_sum_i
            return max_sum_val

        non_empty_indices = [i for i in range(len(bag_state_tuple)) if len(bag_state_tuple[i]) > 0]
        if not non_empty_indices:
            chosen_bag = 0  # Default, should not happen
        else:
            best_i = non_empty_indices[0]
            best_sum = exp_sum_if_pick(remaining_picks, bag_state_tuple, best_i)
            for i in non_empty_indices[1:]:
                exp_sum_i = exp_sum_if_pick(remaining_picks, bag_state_tuple, i)
                if exp_sum_i > best_sum:
                    best_sum = exp_sum_i
                    best_i = i
            chosen_bag = best_i

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=chosen_bag, type='custom')]
        )

